   129→func connectToBastion(config Config, timeout time.Duration) (*ssh.Client, error) {
   130→	var authMethods []ssh.AuthMethod
   131→
   132→	if config.BastionPassword != "" {
   133→		authMethods = append(authMethods, ssh.Password(config.BastionPassword))
   134→	} else {
   135→		var keyData []byte
   136→		var err error
   137→
   138→		if config.BastionKey != "" {
   139→			keyData = []byte(config.BastionKey)
   140→		} else if config.BastionKeyPath != "" {
   141→			keyData, err = os.ReadFile(ExpandPath(config.BastionKeyPath))
   142→			if err != nil {
   143→				return nil, fmt.Errorf("failed to read bastion key file: %w", err)
   144→			}
   145→		} else {
   146→			if config.PrivateKey != "" {
   147→				keyData = []byte(config.PrivateKey)
   148→			} else if config.KeyPath != "" {
   149→				keyData, err = os.ReadFile(ExpandPath(config.KeyPath))
   150→				if err != nil {
   151→					return nil, fmt.Errorf("failed to read key file for bastion: %w", err)
   152→				}
   153→			} else {
   154→				return nil, fmt.Errorf("no SSH key configured for bastion host")
   155→			}
   156→		}
   157→
   158→		signer, err := ssh.ParsePrivateKey(keyData)
   159→		if err != nil {
   160→			return nil, fmt.Errorf("failed to parse bastion SSH key: %w", err)
   161→		}
   162→		authMethods = append(authMethods, ssh.PublicKeys(signer))
   163→	}
   164→
   165→	bastionUser := config.BastionUser
   166→	if bastionUser == "" {
   167→		bastionUser = config.User
   168→	}
   169→
   170→	bastionPort := config.BastionPort
   171→	if bastionPort == 0 {
   172→		bastionPort = 22
   173→	}
   174→
   175→	hostKeyCallback, err := buildHostKeyCallback(config)
   176→	if err != nil {
   177→		return nil, fmt.Errorf("failed to configure host key verification for bastion: %w", err)
   178→	}
   179→
   180→	bastionConfig := &ssh.ClientConfig{
   181→		User:            bastionUser,
   182→		Auth:            authMethods,
   183→		HostKeyCallback: hostKeyCallback,
   184→		Timeout:         timeout,
   185→	}
   186→
   187→	bastionAddr := fmt.Sprintf("%s:%d", config.BastionHost, bastionPort)
   188→	return ssh.Dial("tcp", bastionAddr, bastionConfig)
   189→}
   190→
   191→func buildHostKeyCallback(config Config) (ssh.HostKeyCallback, error) {
   192→	if config.InsecureIgnoreHostKey {
   193→		return ssh.InsecureIgnoreHostKey(), nil
   194→	}
   195→
   196→	if config.KnownHostsFile != "" {
   197→		expandedPath := ExpandPath(config.KnownHostsFile)
   198→		callback, err := knownhosts.New(expandedPath)
   199→		if err != nil {
   200→			return nil, fmt.Errorf("failed to load known_hosts file %s: %w", expandedPath, err)
   201→		}
   202→		return callback, nil
   203→	}
   204→
   205→	homeDir, err := os.UserHomeDir()
   206→	if err == nil {
   207→		defaultKnownHosts := filepath.Join(homeDir, ".ssh", "known_hosts")
   208→		if _, err := os.Stat(defaultKnownHosts); err == nil {
   209→			callback, err := knownhosts.New(defaultKnownHosts)
   210→			if err == nil {
   211→				return callback, nil
   212→			}
   213→		}
   214→	}
   215→
   216→	return func(hostname string, remote net.Addr, key ssh.PublicKey) error {
   217→		return nil
   218→	}, nil
   219→}
   220→
   221→// ExpandPath expands ~ to home directory.
   222→func ExpandPath(path string) string {
   223→	if strings.HasPrefix(path, "~/") {
   224→		homeDir, err := os.UserHomeDir()
   225→		if err == nil {
   226→			return filepath.Join(homeDir, path[2:])
   227→		}
   228→	}
   229→	return path
   230→}
   231→
   232→var validOwnerGroupPattern = regexp.MustCompile(`^[a-zA-Z_][a-zA-Z0-9_-]*$|^[0-9]+$`)
   233→
   234→func validateOwnerGroup(name, fieldName string) error {
   235→	if name == "" {
   236→		return nil
   237→	}
   238→	if len(name) > 32 {
   239→		return fmt.Errorf("%s name too long (max 32 characters): %s", fieldName, name)
   240→	}
   241→	if !validOwnerGroupPattern.MatchString(name) {
   242→		return fmt.Errorf("invalid %s name (must be alphanumeric, underscore, hyphen, or numeric): %s", fieldName, name)
   243→	}
   244→	return nil
   245→}
   246→
   247→// ShellQuote returns a shell-escaped version of the string.
   248→func ShellQuote(s string) string {
   249→	if s == "" {
   250→		return "''"
   251→	}
   252→	escaped := strings.ReplaceAll(s, "'", "'\"'\"'")
   253→	return "'" + escaped + "'"
   254→}
   255→
   256→var validModePattern = regexp.MustCompile(`^[0-7]{3,4}$`)
   257→
   258→// ValidateMode checks if a file mode string is valid.
   259→func ValidateMode(mode string) error {
   260→	if mode == "" {
   261→		return nil
   262→	}
   263→	if !validModePattern.MatchString(mode) {
   264→		return fmt.Errorf("invalid mode %q: must be 3-4 octal digits (e.g., \"644\", \"0755\")", mode)
   265→	}
   266→	return nil
   267→}
